function sha256Pure(text) {
  const bytes = unescape(encodeURIComponent(text));
  const bitLength = bytes.length * 8;
  let data = bytes + '\x80';
  while (data.length % 64 !== 56) data += '\x00';
  data += String.fromCharCode(0, 0, 0, 0, (bitLength >>> 24) & 255, (bitLength >>> 16) & 255, (bitLength >>> 8) & 255, bitLength & 255);
  const initial = [], constants = [], composites = {};
  for (let candidate = 2, count = 0; count < 64; candidate++) {
    if (!composites[candidate]) {
      for (let multiple = candidate * 2; multiple < 400; multiple += candidate) composites[multiple] = true;
      if (count < 8) initial.push((Math.sqrt(candidate) * 0x100000000) | 0);
      constants.push((Math.cbrt(candidate) * 0x100000000) | 0);
      count++;
    }
  }
  const hash = initial.slice(), rotate = (value, bits) => (value >>> bits) | (value << (32 - bits));
  for (let offset = 0; offset < data.length; offset += 64) {
    const words = new Array(64);
    for (let index = 0; index < 16; index++) {
      const start = offset + index * 4;
      words[index] = (data.charCodeAt(start) << 24) | (data.charCodeAt(start + 1) << 16) | (data.charCodeAt(start + 2) << 8) | data.charCodeAt(start + 3);
    }
    for (let index = 16; index < 64; index++) {
      const x = words[index - 15], y = words[index - 2];
      words[index] = (words[index - 16] + (rotate(x, 7) ^ rotate(x, 18) ^ (x >>> 3)) + words[index - 7] + (rotate(y, 17) ^ rotate(y, 19) ^ (y >>> 10))) | 0;
    }
    let [a, b, c, d, e, f, g, h] = hash;
    for (let index = 0; index < 64; index++) {
      const t1 = (h + (rotate(e, 6) ^ rotate(e, 11) ^ rotate(e, 25)) + ((e & f) ^ (~e & g)) + constants[index] + words[index]) | 0;
      const t2 = ((rotate(a, 2) ^ rotate(a, 13) ^ rotate(a, 22)) + ((a & b) ^ (a & c) ^ (b & c))) | 0;
      h = g; g = f; f = e; e = (d + t1) | 0; d = c; c = b; b = a; a = (t1 + t2) | 0;
    }
    hash[0] = (hash[0] + a) | 0; hash[1] = (hash[1] + b) | 0; hash[2] = (hash[2] + c) | 0; hash[3] = (hash[3] + d) | 0;
    hash[4] = (hash[4] + e) | 0; hash[5] = (hash[5] + f) | 0; hash[6] = (hash[6] + g) | 0; hash[7] = (hash[7] + h) | 0;
  }
  return hash.map(value => (value >>> 0).toString(16).padStart(8, '0')).join('');
}

const input = $input.item.json;
const raw = input.body && typeof input.body === 'object' ? input.body : input;
const value = item => item == null ? '' : String(item).trim();
const email = value(raw.email || raw.email_client).toLowerCase();
const domain = email.includes('@') ? email.split('@').pop().replace(/^www\./, '') : '';
const entreprise_client = value(raw.entreprise_client || raw.entity) || (domain ? 'Société via ' + domain : '');
if (!entreprise_client) throw new Error('Entreprise absente : renseignez le nom légal ou un e-mail professionnel valide.');
const aliases = { agro: 'agro', banque: 'banque', finance: 'banque', banking: 'banque', financialservices: 'banque', mines: 'mines', energy: 'mines', energie: 'mines', logistique: 'logistique', logistics: 'logistique', sante: 'sante', health: 'sante', telecom: 'telecoms', telecoms: 'telecoms', btp: 'btp', property: 'btp', industrie: 'industrie', manufacturing: 'industrie', public: 'public', retail: 'retail' };
const sectorInput = value(raw.secteur || raw.sector || raw.secteur_selectionne).toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-z]/g, '');
const secteur = aliases[sectorInput];
if (!secteur) throw new Error('Secteur absent ou non reconnu dans le contrat d’interface.');
const palierInput = value(raw.palier).toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
const palier = /decouverte|discovery|starter/.test(palierInput) ? 'decouverte' : /chambre|executive|executif/.test(palierInput) ? 'chambre' : 'mandat';
const currencyInput = value(raw.currency).toUpperCase();
const currency = ['EUR', 'USD', 'FCFA'].includes(currencyInput) ? currencyInput : 'EUR';
const reference_mission = value(raw.reference_mission || raw.reference) || 'MIS-' + new Date().getUTCFullYear() + '-' + String(Math.floor(Math.random() * 10000)).padStart(4, '0');
const nom_client = value(raw.nom_client || raw.representant) || (email.includes('@') ? email.split('@')[0].replace(/[._-]+/g, ' ') : 'Direction requérante');
const whatsapp = value(raw.whatsapp || raw.telephone_client).replace(/\D/g, '').replace(/^00/, '');
const problematique = value(raw.problematique || raw.mission_contexte || raw.problematique_brute);
const parsedDate = new Date(raw.date_analyse_utc || raw.date || Date.now());
const date_analyse_utc = Number.isNaN(parsedDate.getTime()) ? new Date().toISOString() : parsedDate.toISOString();
const titre_mission = 'Audit Stratégique [' + secteur.toUpperCase() + '] — ' + entreprise_client;
const canonical = { reference_mission, entreprise_client, nom_client, secteur, palier, currency, problematique, email, whatsapp, date_analyse_utc, titre_mission };
const sha256_hash = sha256Pure(JSON.stringify(canonical));
if (raw.sha256_hash && value(raw.sha256_hash).toLowerCase() !== sha256_hash) throw new Error('L’empreinte SHA-256 transmise ne correspond pas aux métadonnées canoniques.');
const guides = { agro: 'Rendement, pertes post-recolte et chaine du froid.', banque: 'Liquidite, qualite des actifs, cout du risque et exigences BCEAO/UEMOA applicables.', mines: 'Couts d?extraction, teneur, redevances, contenu local et dependances energetiques.', logistique: 'Cout par tonne-kilometre, delais, taux de service et continuite des corridors.', sante: 'Disponibilite, chaine du froid, securite patient et conformite applicable.', telecoms: 'ARPU, churn, disponibilite, SLA et cout par abonne.', btp: 'Marge chantier, derives de cout/delai, BFR et documentation fonciere.', industrie: 'TRS/OEE, rebuts, energie et maintenance.', public: 'Execution budgetaire, delais, tracabilite et conformite des marches.', retail: 'Rotation des stocks, demarque, marge et BFR.' };
const matrice_probatoire = {
