  logistique: { references_legales: ['Acte uniforme OHADA relatif au droit comptable et a l?information financiere, si applicable', 'Regles douanieres, portuaires et de transport du territoire concerne, a verifier', 'Convention de transport applicable au mode et aux pays concernes, a verifier'], sources_metier: ['ISO 28000, si adoptee ou certifiee', 'Donnees portuaires/douanieres officielles et datees', 'Journaux GPS, preuves de livraison et couts par corridor'], pieces_manquantes: ['Bons de chargement et de livraison contradictoires', 'Factures transporteurs rapproch?es aux preuves de service', 'Journaux d?incidents, retards et ruptures de charge'] },
  sante: { references_legales: ['Reglementation sanitaire et pharmaceutique nationale, textes et autorites a verifier', 'Regles nationales de protection des donnees de sante, a verifier', 'Acte uniforme OHADA relatif au droit comptable et a l?information financiere, si applicable'], sources_metier: ['ISO 15189, si laboratoire et certification concernes', 'Guides OMS applicables au service et a la chaine du froid', 'Donnees de disponibilite, qualite et securite patient sourcees'], pieces_manquantes: ['Registres de lots, temperatures et excursions', 'Rapports d?incidents et dossiers de conformite anonymises', 'Rapprochements stocks, consommations et facturations'] },
  telecoms: { references_legales: ['Licence et decisions de l?autorite nationale de regulation, references a verifier', 'Regles nationales de donnees personnelles et telecommunications, a verifier', 'Acte uniforme OHADA relatif au droit comptable et a l?information financiere, si applicable'], sources_metier: ['Indicateurs publies par l?autorite nationale et l?UIT, periode a preciser', 'ISO/IEC 27001, si adoptee ou certifiee', 'Mesures SLA, disponibilite, trafic et churn horodatees'], pieces_manquantes: ['Journaux d?incident reseau et calculs SLA contradictoires', 'Echantillons anonymises de facturation et churn', 'Rapports de couverture et mesures terrain independantes'] },
