  industrie: { references_legales: ['Acte uniforme OHADA relatif au droit comptable et a l?information financiere, si applicable', 'Regles nationales de securite industrielle, environnement et travail, a verifier', 'Normes techniques rendues obligatoires par le secteur et le pays, a verifier'], sources_metier: ['ISO 9001 / ISO 14001 / ISO 45001, si adoptees ou certifiees', 'Journaux de production, TRS/OEE et maintenance avec provenance', 'Donnees metrologiques et de consommation energetique datees'], pieces_manquantes: ['Contre-inventaire des stocks et encours', 'Journaux machine, arr?ts et rebuts rapproches aux ordres de production', 'Rapports d?etalonnage et factures energetiques'] },
  public: { references_legales: ['Droit national des finances publiques et de la commande publique, textes a verifier', 'Regles de controle et de comptabilite publique applicables, a verifier', 'Acte uniforme OHADA uniquement si le statut de l?entite le rend applicable'], sources_metier: ['Budgets, lois de reglement et donnees d?execution officielles', 'Rapports publics de juridictions financieres et organes de controle', 'ISO 37001, si adoptee ou certifiee'], pieces_manquantes: ['Pieces de marche et preuves de mise en concurrence', 'Engagements, liquidations, ordonnancements et paiements rapproches', 'Proces-verbaux de reception contradictoires et audits de controle'] },
  retail: { references_legales: ['Acte uniforme OHADA relatif au droit comptable et a l?information financiere, si applicable', 'Regles nationales de consommation, concurrence et fiscalite, a verifier', 'Regles nationales de protection des donnees personnelles, si traitement concerne'], sources_metier: ['Journaux de caisse/POS et donnees de stocks datees', 'Donnees officielles de prix et d?inflation, periode et source a preciser', 'ISO 9001, si adoptee ou certifiee'], pieces_manquantes: ['Inventaire physique contradictoire par site', 'Exports POS, retours, remises et annulations rapproches', 'Factures fournisseurs, receptions et avoirs rapproches'] }
