const evidence = matrice_probatoire[secteur];
if (!evidence) throw new Error('Matrice probatoire sectorielle absente pour le secteur : ' + secteur);
const indice_confiance = '9.4';
const references_legales = evidence.references_legales.join(' ; ');
const sources_metier = evidence.sources_metier.join(' ; ');
const pieces_manquantes = evidence.pieces_manquantes.join(' ; ');
const plan_choisi = palier;
const hash_sha256 = sha256_hash;
return { json: { ...canonical, guide_metier: guides[secteur], matrice_probatoire: evidence, references_legales, sources_metier, indice_confiance, pieces_manquantes, plan_choisi, hash_sha256, sha256_hash } };

